(function(){
"use strict";
/* ══════ LIVING MOSAIC — THE BLOG BACKDROP ══════
   One fixed canvas behind the page, sharing the site's tessera DNA:
   Tile pitch: max(vw,vh)/130 device px — identical to every other page;
               pitch re-derived on width/DPR change only (mobile URL-bar safe).
   Tile body:  same rbox crystal-facet shader (fill 0.87, sheen, bevel,
               sparkle, grade exp 1.28 / gamma 1.30 / sat 1.22).
   Art:        baked from the nebula reference — dark centre lane, colour
               at the edges, so the copy sits on the quiet part.
   Motion:     deliberately calmer than /services/ — twinkling star tiles,
               a slow nebula breath (mid-luminance tiles only, own hue),
               a shooting glint every ~22s, and the gravity lens on hover.
               After ~2.6s idle a phantom cursor drifts along the nebula
               edge so the page never looks frozen; real input overrides. */

const G=130;
const BG_B64="";
const SPARK_B64="";

/* ── tuning knobs ── */
const ART_DIM=1.0;        // 0.85 for an even quieter field; 1.0 = faithful bake
const BREATH=0.10;        // nebula breath amplitude (services uses ~0.3–0.55)
const LENS=0.42;          // gravity-lens lift (services: 0.55)
const SHOOT_EVERY=22000;  // ms between shooting glints (services: 14000)
const FOCAL=[65,65];      // grid centre to crop around

const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function b64ToBytes(b64){const bin=atob(b64),n=bin.length,out=new Uint8Array(n);for(let i=0;i<n;i++)out[i]=bin.charCodeAt(i);return out;}
const bgRGB=b64ToBytes(BG_B64);
const sparkU8=b64ToBytes(SPARK_B64);

const VS=`#version 300 es
precision highp float;
layout(location=0) in vec2 a_quad;
layout(location=1) in vec2 a_grid;
layout(location=2) in vec3 a_color;
layout(location=3) in float a_spark;
uniform vec2 u_res; uniform vec2 u_origin; uniform float u_tilePx; uniform float u_fill;
uniform float u_time;
uniform float u_breath; uniform float u_lens;
uniform vec3 u_drive;
uniform float u_shootOn; uniform vec2 u_shootHead; uniform vec2 u_shootDir;
out vec2 v_local; out vec3 v_color; out float v_glow; out float v_lift;
void main(){
  v_local=a_quad; v_color=a_color;
  float h=fract(sin(dot(a_grid,vec2(12.9898,78.233)))*43758.5453);
  float tw=a_spark*0.50*(0.5+0.5*sin(u_time*(0.7+1.4*h)+h*6.2831));

  /* nebula breath: two slow incommensurate waves crossing the field,
     gated to mid-luminance tiles so deep space and stars stay still */
  float lum=dot(a_color,vec3(0.299,0.587,0.114));
  float gate=smoothstep(0.06,0.16,lum)*(1.0-smoothstep(0.30,0.48,lum));
  float w1=sin(u_time*0.11+a_grid.x*0.09-a_grid.y*0.05);
  float w2=sin(u_time*0.073-a_grid.x*0.04+a_grid.y*0.11+h*1.7);
  v_lift=u_breath*gate*(0.5*w1+0.5*w2);

  /* gravity lens: lift, brighten and lean toward the drive point */
  vec2 dm=a_grid-u_drive.xy;
  float g=exp(-dot(dm,dm)/26.0)*u_drive.z;
  v_lift+=g*u_lens;

  /* shooting glint */
  vec2 rel=u_shootHead-a_grid;
  float along=dot(rel,u_shootDir);
  vec2 perp=rel-along*u_shootDir;
  float trail=(along>-0.6&&along<15.0)?exp(-max(along,0.0)*0.32):0.0;
  float sh=u_shootOn*trail*max(0.0,1.0-length(perp)/1.15);
  v_glow=clamp(tw+sh*1.25+g*0.10,0.0,1.6);

  float size=u_tilePx*u_fill*(1.0+0.12*g);
  vec2 c=u_origin+(a_grid+vec2(0.5))*u_tilePx;
  c-=dm/(length(dm)+0.6)*g*0.20*u_tilePx;   /* lean toward the lens */
  vec2 px=c+a_quad*size;
  gl_Position=vec4(px.x/u_res.x*2.0-1.0, 1.0-px.y/u_res.y*2.0, 0.0, 1.0);
}`;

const FS=`#version 300 es
precision highp float;
in vec2 v_local; in vec3 v_color; in float v_glow; in float v_lift; out vec4 frag;
uniform float u_exp; uniform float u_gamma; uniform float u_sat; uniform float u_dim;
float rbox(vec2 p, vec2 b, float r){vec2 q=abs(p)-b+r;return length(max(q,0.0))+min(max(q.x,q.y),0.0)-r;}
void main(){
  vec2 p=v_local;
  float d=rbox(p,vec2(0.5),0.16);
  float aa=fwidth(d)*1.25;
  float mask=smoothstep(aa,-aa,d);
  if(mask<=0.002) discard;
  float edge=-d;

  // true colour, gently lifted — identical grade to the landing mosaic
  vec3 col=pow(clamp(v_color*u_dim*u_exp,0.0,1.0), vec3(1.0/u_gamma));
  float l=dot(col,vec3(0.299,0.587,0.114));
  col=mix(vec3(l),col,u_sat);

  col*=(1.0+v_lift);                                        // breath / lens in the tile's own hue

  // crystal facets: additive only, colour never muddies
  col+=smoothstep(0.5,-0.5,p.y)*0.05;                       // top sheen
  float rim=smoothstep(0.0,0.07,edge)*(1.0-smoothstep(0.07,0.16,edge));
  col+=rim*0.22;                                            // bright bevelled edge
  vec2 sp=p-vec2(-0.20,-0.24);
  col+=exp(-dot(sp,sp)*16.0)*0.16;                          // crisp specular sparkle

  col+=v_glow*vec3(1.0,0.95,0.80);                          // twinkle + shooting glint

  col=clamp(col,0.0,1.3);
  float alpha=min(1.0,0.92+v_glow*0.08)*mask;
  frag=vec4(col,alpha);
}`;

function makeBackdrop(cfg){
  const canvas=document.getElementById(cfg.id);
  if(!canvas) return;
  const holder=canvas.parentElement;
  const gl=canvas.getContext('webgl2',{alpha:true,premultipliedAlpha:false,antialias:true});
  if(!gl){ canvas.style.display='none'; return; }   // container gradient remains as graceful fallback

  function compile(t,s){const sh=gl.createShader(t);gl.shaderSource(sh,s);gl.compileShader(sh);
    if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS)){console.error(gl.getShaderInfoLog(sh));return null;}return sh;}
  const prog=gl.createProgram();
  const vs=compile(gl.VERTEX_SHADER,VS), fs=compile(gl.FRAGMENT_SHADER,FS);
  if(!vs||!fs){canvas.style.display='none';return;}
  gl.attachShader(prog,vs);gl.attachShader(prog,fs);gl.linkProgram(prog);
  if(!gl.getProgramParameter(prog,gl.LINK_STATUS)){console.error(gl.getProgramInfoLog(prog));canvas.style.display='none';return;}
  gl.useProgram(prog);

  const U={};
  ['u_res','u_origin','u_tilePx','u_fill','u_time','u_breath','u_lens','u_drive',
   'u_shootOn','u_shootHead','u_shootDir','u_exp','u_gamma','u_sat','u_dim']
    .forEach(n=>U[n]=gl.getUniformLocation(prog,n));
  gl.uniform1f(U.u_fill,0.87);
  gl.uniform1f(U.u_exp,1.28); gl.uniform1f(U.u_gamma,1.30); gl.uniform1f(U.u_sat,1.22);
  gl.uniform1f(U.u_dim,ART_DIM);
  gl.uniform1f(U.u_breath,reduceMotion?0:BREATH);
  gl.uniform1f(U.u_lens,LENS);
  gl.uniform3f(U.u_drive,-999,-999,0);
  gl.uniform1f(U.u_shootOn,0); gl.uniform2f(U.u_shootHead,-99,-99); gl.uniform2f(U.u_shootDir,1,0);

  gl.enable(gl.BLEND);
  gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);
  gl.clearColor(0,0,0,0);

  const quad=new Float32Array([-0.5,-0.5,0.5,-0.5,0.5,0.5,-0.5,-0.5,0.5,0.5,-0.5,0.5]);
  const qb=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,qb); gl.bufferData(gl.ARRAY_BUFFER,quad,gl.STATIC_DRAW);

  function makeSet(gridArr,colArr,sparkArr,count){
    const vao=gl.createVertexArray(); gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER,qb);
    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0,2,gl.FLOAT,false,0,0);
    function attr(loc,arr,size){const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);
      gl.bufferData(gl.ARRAY_BUFFER,arr,gl.STATIC_DRAW);
      gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,0,0);gl.vertexAttribDivisor(loc,1);}
    attr(1,gridArr,2); attr(2,colArr,3); attr(3,sparkArr,1);
    gl.bindVertexArray(null);
    return {vao,count};
  }

  let DPR=1,tilePx=1,bw=0,bh=0,cols=0,rows=0,col0=0,row0=0,bgSet=null,ox=0,oy=0;
  let lockedW=-1,lockedDPR=-1;
  function layout(){
    DPR=Math.min(window.devicePixelRatio||1,2);
    if(window.innerWidth!==lockedW||DPR!==lockedDPR){
      /* pitch derived from the viewport like every other page, but only
         re-derived on a width or DPR change — height-only resizes (mobile
         URL bar) leave the artwork's scale untouched. */
      lockedW=window.innerWidth; lockedDPR=DPR;
      const vw=Math.round(window.innerWidth*DPR), vh=Math.round(window.innerHeight*DPR);
      tilePx=Math.max(vw/G,vh/G);
    }
    const rect=holder.getBoundingClientRect();
    bw=Math.max(1,Math.round(rect.width*DPR)); bh=Math.max(1,Math.round(rect.height*DPR));
    canvas.width=bw; canvas.height=bh;
    gl.viewport(0,0,bw,bh);
    cols=Math.min(G,Math.ceil(bw/tilePx)+1);
    rows=Math.min(G,Math.ceil(bh/tilePx)+1);
    col0=Math.max(0,Math.min(G-cols,Math.round(cfg.focalCol-cols/2)));
    row0=Math.max(0,Math.min(G-rows,Math.round(cfg.focalRow-rows/2)));
    ox=(bw-cols*tilePx)/2; oy=(bh-rows*tilePx)/2;
    const n=cols*rows;
    const gArr=new Float32Array(n*2), cArr=new Float32Array(n*3), sArr=new Float32Array(n);
    let k=0;
    for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
      const src=((row0+r)*G+(col0+c));
      gArr[k*2]=c; gArr[k*2+1]=r;
      cArr[k*3]=bgRGB[src*3]/255; cArr[k*3+1]=bgRGB[src*3+1]/255; cArr[k*3+2]=bgRGB[src*3+2]/255;
      sArr[k]=sparkU8[src]/255;
      k++;
    }
    bgSet=makeSet(gArr,cArr,sArr,n);
    gl.uniform2f(U.u_res,bw,bh);
    gl.uniform1f(U.u_tilePx,tilePx);
  }
  layout();
  let resizeT=null;
  window.addEventListener('resize',()=>{clearTimeout(resizeT);resizeT=setTimeout(()=>{layout();if(!running)draw(lastT);},120);});

  /* ── unified drive: real pointer (window-level, so the lens shines through
        the glass shell), or a phantom drifting along the nebula edge ── */
  const drive={x:-999,y:-999,amt:0,tx:-999,ty:-999,tAmt:0,lastMove:-1e9};
  if(!reduceMotion){
    window.addEventListener('pointermove',e=>{
      drive.tx=(e.clientX*DPR-ox)/tilePx;
      drive.ty=(e.clientY*DPR-oy)/tilePx;
      drive.lastMove=performance.now();
    },{passive:true});
    document.documentElement.addEventListener('pointerleave',()=>{drive.lastMove=performance.now()-1800;},{passive:true});
  }
  function driveStep(now){
    if(reduceMotion){gl.uniform3f(U.u_drive,-999,-999,0);return;}
    const idle=now-drive.lastMove>2600;
    if(idle){
      /* phantom cursor: a slow figure-eight hugging the left/right nebulae,
         never crossing the centre reading lane */
      const a=now*0.00022;
      drive.tx=cols*0.5+Math.sin(a)*cols*0.42;
      drive.ty=rows*0.5+Math.sin(a*2.0+1.1)*rows*0.30;
      drive.tAmt=0.55;
    }else{
      drive.tAmt=1.0;
    }
    if(drive.x<-500){drive.x=drive.tx;drive.y=drive.ty;}
    drive.x+=(drive.tx-drive.x)*0.14;
    drive.y+=(drive.ty-drive.y)*0.14;
    drive.amt+=(drive.tAmt-drive.amt)*0.08;
    gl.uniform3f(U.u_drive,drive.x,drive.y,drive.amt);
  }

  /* ── shooting glint ── */
  const shoot={on:false,t0:0,dur:1.6,head:[0,0],dir:[1,0],start:[0,0],dist:0,next:performance.now()+cfg.shootEvery*(0.2+Math.random()*0.3)};
  function shootStep(now){
    if(!cfg.shootEvery) return;
    if(!shoot.on && now>=shoot.next){
      shoot.on=true; shoot.t0=now;
      const fromLeft=Math.random()<0.5;
      const ang=(0.30+Math.random()*0.22)*(fromLeft?1:-1)+(fromLeft?0:Math.PI);
      shoot.dir=[Math.cos(ang),Math.abs(Math.sin(ang))*0.55+0.18];
      const len=Math.hypot(shoot.dir[0],shoot.dir[1]); shoot.dir[0]/=len; shoot.dir[1]/=len;
      shoot.start=[fromLeft?-6:cols+6, 1+Math.random()*rows*0.45];
      shoot.dist=cols+14;
    }
    if(shoot.on){
      const p=(now-shoot.t0)/(shoot.dur*1000);
      if(p>=1){ shoot.on=false; shoot.next=now+cfg.shootEvery*(0.6+Math.random()*0.9);
        gl.uniform1f(U.u_shootOn,0); gl.uniform2f(U.u_shootHead,-99,-99); return; }
      const fade=p<0.12?p/0.12:(p>0.8?(1-p)/0.2:1);
      shoot.head=[shoot.start[0]+shoot.dir[0]*shoot.dist*p, shoot.start[1]+shoot.dir[1]*shoot.dist*p];
      gl.uniform1f(U.u_shootOn,fade);
      gl.uniform2f(U.u_shootHead,shoot.head[0],shoot.head[1]);
      gl.uniform2f(U.u_shootDir,shoot.dir[0],shoot.dir[1]);
    }
  }

  let lastT=0;
  function draw(now){
    lastT=now;
    gl.uniform1f(U.u_time,now*0.001);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform2f(U.u_origin,ox,oy);
    gl.bindVertexArray(bgSet.vao);
    gl.drawArraysInstanced(gl.TRIANGLES,0,6,bgSet.count);
    gl.bindVertexArray(null);
  }

  /* ── run loop: only while the tab is visible, never under reduced motion ── */
  let running=false, raf=0;
  function loop(now){ if(!running) return; driveStep(now); shootStep(now); draw(now); raf=requestAnimationFrame(loop); }
  function setRunning(v){
    if(v===running) return;
    running=v;
    if(v) raf=requestAnimationFrame(loop); else cancelAnimationFrame(raf);
  }
  if(reduceMotion){
    draw(performance.now());   // one still frame — full mosaic, no motion
  }else{
    document.addEventListener('visibilitychange',()=>setRunning(!document.hidden));
    setRunning(!document.hidden);
  }
}

makeBackdrop({
  id:'mosaic-blog',
  focalRow:FOCAL[1], focalCol:FOCAL[0],
  shootEvery:SHOOT_EVERY
});
})();
